    @Test
    public void testSetPosition_AllBranches() {
        // We use a spy to control the behavior of the method being tested's dependencies (itself)
        AttributeContext spyContext = spy(new AttributeContext(parentContext, nodeTest));

        // Branch 1: position < getCurrentPosition() -> calls reset()
        doReturn(10).when(spyContext).getCurrentPosition();
        doNothing().when(spyContext).reset();
        // After reset, let's say position is 5. The loop condition (5 < 5) is false.
